def _design(tau, history, hold, x, dt, times):
    state = np.zeros((len(hold), 2))
    for (duration, stress) in zip(dt, history.T):
        uptake = -np.expm1(-duration / tau)
        state += uptake * (stress[:, None] - state)
    gap = hold[:, None] - state
    (b, r) = _basis(tau, times)
    curves = np.concatenate((gap[:, None, :] * b[None, :, :2], times[None, :, None] * x[:, None, :]), axis=-1)
    return np.vstack((curves.reshape(-1, 7), np.column_stack((gap * r[:2], x))))

def _fit(samples, dt, times, strain, rate):
    from scipy.optimize import least_squares
    y = np.concatenate((strain.ravel(), rate))
    n_curve = strain.size
    bounds = (np.r_[np.log([0.05000001, 0.05000001]), [-np.inf] * 7], np.r_[np.log([24.999999, 24.999999]), [np.inf] * 7])

    def matrix(u):
        (cur, slope) = _design(u, samples, dt, times)
        return np.vstack((cur.reshape(-1, 7), slope))
    grid = np.geomspace(0.085, 20.0, 12)
    best = float('inf')
    for (i, fast) in enumerate(grid[:-1]):
        for slow in grid[i + 1:]:
            u = np.log([fast, slow])
            a = matrix(u)
            theta = np.linalg.lstsq(a, y, rcond=None)[0]
            err = a @ theta - y
            cost = np.mean(np.minimum(err[:n_curve] ** 2, 0.25 ** 2))
            cost += np.mean(np.minimum(err[n_curve:] ** 2, 0.25 ** 2))
            if cost < best:
                (best, p) = (cost, np.r_[u, theta])

    def refine(p, scale, loss, f_scale):

        def residual(q):
            return (matrix(q[:2]) @ q[2:] - y) / scale

        def jac(q):
            (cur, slope, dc, dr) = _design(q[:2], samples, dt, times, True)
            a = np.vstack((cur.reshape(-1, 7), slope))
            d = np.vstack((dc.reshape(-1, 2), dr)) * q[None, 2:4]
            return np.column_stack((d, a)) / scale[:, None]
        return least_squares(residual, p, jac=jac, bounds=bounds, loss=loss, f_scale=f_scale, x_scale='jac', max_nfev=175).x

    def scales(p):
        err = matrix(p[:2]) @ p[2:] - y
        return np.maximum([_mad(err[:n_curve]), _mad(err[n_curve:])], 1e-07)

    def expand(s):
        return np.repeat(s, [n_curve, len(rate)])
    p = refine(p, expand(scales(p)), 'soft_l1', 1.5)
    p = refine(p, expand(scales(p)), 'cauchy', 2.5)
    order = np.argsort(p[:2])
    return (np.exp(p[order]), np.r_[p[2 + order], p[4:]])
